#include <string>
using namespace std;

class Solution {
public:
    int countHomogenous(string s) {
        const int MOD = 1e9 + 7;
        long long ans = 0;
        int streak = 0;
        char prev = ' ';
        for (char c : s) {
            if (c == prev) {
                streak++;
            } else {
                streak = 1;
                prev = c;
            }
            ans = (ans + streak) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int countHomogenous(String s) {
        final int MOD = 1_000_000_007;
        long ans = 0;
        int streak = 0;
        char prev = ' ';
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            if (c == prev) {
                streak++;
            } else {
                streak = 1;
                prev = c;
            }
            ans = (ans + streak) % MOD;
        }
        return (int)ans;
    }
}

