var countHomogenous = function(s) {
    const MOD = 1000000007;
    let ans = 0;
    let streak = 0;
    let prev = '';
    for (let i = 0; i < s.length; ++i) {
        const c = s[i];
        if (c === prev) {
            streak++;
        } else {
            streak = 1;
            prev = c;
        }
        ans = (ans + streak) % MOD;
    }
    return ans;
};
